-- Naxxramas: the Classic armor, jewelry, cloaks, shields and off-hands that drop there had no item row
-- (the WoW Forever client blanks them), so every one was an invalid loot item and nothing dropped. Rows from the
-- Classic item data: stats as budget shares, armor from the item level formula, Classic sell prices, Classic
-- equip and use spells as item effects, hotfix_data so the client shows them.
DELETE FROM `item_sparse` WHERE `ID` IN (22936,22938,22960,22983,23000,23017,23021,23030,23035,23068,23069,23070,23073,23219,23220,23226,23663,23664,23665,23666,23667,23668);
DELETE FROM `item_effect` WHERE `ID` BETWEEN 9900678 AND 9900717;
DELETE FROM `item_x_item_effect` WHERE `ID` BETWEEN 9900678 AND 9900717;
DELETE FROM `hotfix_data` WHERE `Id` BETWEEN 26113221 AND 26113322;
